const assamData={roof:{title:"Sloping Roof (GCI Sheets/Thatch)",description:"Assam Type houses feature highly pitched roofs, historically made of thatch but later replaced by Galvanized Corrugated Iron (GCI) sheets introduced by the British.",adaptation:"The steep slope ensures that the heavy monsoon rain runs off quickly, preventing waterlogging and structural damage. The overhanging eaves protect the walls from driving rain.",materials:"GCI sheets, timber trusses, and sometimes traditional thatch in rural adaptations."},timber:{title:"Timber Framework",description:"The structural skeleton of the house is built entirely of timber, creating a lightweight but extremely strong matrix.",adaptation:"This timber frame provides incredible seismic resilience. During an earthquake, the wooden joints flex and sway rather than cracking or collapsing like rigid masonry.",materials:"Local hardwoods such as Sal, Teak, and Bonsum, which are naturally resistant to termites and rot."},ikra:{title:"Ikra Walls (Wattle and Daub)",description:"The walls are non-load-bearing, constructed using 'Ikra' (a local reed) woven into a bamboo matrix and plastered with mud or cement.",adaptation:"Because the walls are incredibly lightweight, they significantly reduce the dead load of the building. If they fall during a massive earthquake, they cause minimal injury compared to brick walls. They also provide excellent thermal insulation.",materials:"Ikra reeds, bamboo lattice, mud plaster mixed with cow dung, or modern cement plaster."},stilt:{title:"Stilts / High Plinth (Chang Ghar)",description:"Traditionally, many houses (especially the 'Chang Ghar' of the Mising tribe) are built on stilts. In urban areas, this evolved into a very high brick or concrete plinth.",adaptation:"Protects the living quarters from the severe annual floods of the Brahmaputra River. It also keeps the floor dry from the damp soil and prevents wild animals and insects from entering.",materials:"Bamboo or timber poles in traditional structures; brick and cement masonry in colonial and modern Assam Type houses."}};document.addEventListener("DOMContentLoaded",()=>{const e=document.querySelectorAll(".diag-section"),t=document.getElementById("section-title"),a=document.getElementById("section-description"),i=document.getElementById("section-meta"),n=document.getElementById("meta-adaptation"),r=document.getElementById("meta-materials");e.forEach(o=>{o.addEventListener("click",()=>{e.forEach(e=>e.classList.remove("active"));const s=o.getAttribute("data-section");document.querySelectorAll(`[data-section="${s}"]`).forEach(e=>e.classList.add("active"));const l=assamData[s];l&&(t.textContent=l.title,a.textContent=l.description,n.textContent=l.adaptation,r.textContent=l.materials,i.classList.remove("hidden"))})})});